import{_ as i,o,c as d,ai as a}from"./chunks/framework.COht06hG.js";const h=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),c={name:"guide/index.md"};function l(n,e,r,t,s,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to “介绍”">​</a></h1><p><code>uniapp-template</code> 是一个基于 <code>uni-app + Vue 3 + Vite</code> 的多端项目模板。它更偏向“业务启动模板 + 多端能力示例”，不是单纯的空白脚手架。</p><h2 id="已集成能力" tabindex="-1">已集成能力 <a class="header-anchor" href="#已集成能力" aria-label="Permalink to “已集成能力”">​</a></h2><ul><li><code>@uni-helper/unh</code>：封装开发、构建和配置生成流程。</li><li><code>@uni-helper/vite-plugin-uni-pages</code>：基于文件约定和 <code>definePage</code> 生成页面配置。</li><li><code>@uni-helper/vite-plugin-uni-manifest</code>：通过 <code>manifest.config.js</code> 维护应用配置。</li><li><code>Pinia</code>：管理登录态、用户信息、TabBar 和主题相关状态。</li><li><code>Wot UI</code>：通过 <code>pages.config.js</code> 的 <code>easycom</code> 自动解析 <code>wd-*</code> 组件。</li><li><code>Tailwind CSS 4 + weapp-tailwindcss</code>：提供多端可用的原子类写法。</li><li><code>better-mock</code>：开发环境可开启本地 Mock。</li><li><code>@uni-ku/bundle-optimizer</code>：优化微信小程序分包体积，并支持跨包异步引用示例。</li></ul><h2 id="适合做什么" tabindex="-1">适合做什么 <a class="header-anchor" href="#适合做什么" aria-label="Permalink to “适合做什么”">​</a></h2><ul><li>快速启动 H5 或微信小程序业务项目。</li><li>验证登录、角色权限、动态 TabBar、暗黑模式、字号切换等通用能力。</li><li>作为 uni-app 多端工程化配置的参考项目。</li></ul><h2 id="关键约定" tabindex="-1">关键约定 <a class="header-anchor" href="#关键约定" aria-label="Permalink to “关键约定”">​</a></h2><ul><li>使用 <code>pnpm</code> 安装依赖，项目通过 <code>only-allow pnpm</code> 限制包管理器。</li><li>环境变量集中放在 <code>env/</code> 目录，由 <code>vite.config.js</code> 和 <code>manifest.config.js</code> 读取。</li><li>主包页面放在 <code>src/pages</code>。</li><li>分包放在 <code>src/echarts-modules</code> 和 <code>src/public-modules</code>。</li><li>页面权限写在页面内的 <code>definePage({ rules: [...] })</code> 中。</li></ul>',8)])])}const m=i